"""All writable application state is confined to AXIOM."""import osfrom dataclasses import dataclass, fieldfrom ipaddress import IPv4Address, IPv4Networkfrom pathlib import PathROOT = Path(__file__).resolve().parents[2]@dataclassclass Settings:    root: Path = field(default_factory=lambda: ROOT)    state_dir: Path | None = None    synthetic_mode: bool = False    bind_host: str = "127.0.0.1"    bind_port: int = field(default=8765, init=False)    allow_docker_host: bool = False    def __post_init__(self):        if not isinstance(self.bind_host, str):            raise ValueError("DARLA_BIND_HOST requires a literal IPv4 address")        try:            address = IPv4Address(self.bind_host)        except ValueError as error:            raise ValueError(                "DARLA_BIND_HOST requires a literal IPv4 address, never a wildcard or hostname"            ) from error        private_ranges = (            IPv4Network("10.0.0.0/8"),            IPv4Network("172.16.0.0/12"),            IPv4Network("192.168.0.0/16"),        )        if self.bind_host != "127.0.0.1" and not any(            address in network for network in private_ranges        ):            raise ValueError(                "DARLA_BIND_HOST allows loopback or one explicitly approved RFC1918 interface only"            )        if (self.bind_host != "127.0.0.1" or self.allow_docker_host) and not self.synthetic_mode:            raise ValueError(                "Nonloopback binding and Docker Host opt-in require explicit synthetic mode"            )        self.root = self.root.resolve(strict=True)        if self.root.name != "AXIOM":            raise ValueError("Application root must be AXIOM")        self.state_dir = (self.state_dir or self.root / ".local").resolve()        if not self.state_dir.is_relative_to(self.root) or self.state_dir == self.root:            raise ValueError("State directory must be contained within AXIOM")    @classmethod    def from_environment(cls):        state = os.environ.get("DARLA_STATE_DIR")        return cls(            state_dir=Path(state) if state else None,            synthetic_mode=os.environ.get("DARLA_SYNTHETIC_MODE") == "1",            bind_host=os.environ.get("DARLA_BIND_HOST", "127.0.0.1"),            allow_docker_host=os.environ.get("DARLA_ALLOW_DOCKER_HOST") == "1",        )    @property    def allowed_hosts(self) -> list[str]:        hosts = ["127.0.0.1", "localhost", "testserver"]        if self.bind_host != "127.0.0.1":            hosts.append(self.bind_host)        if self.allow_docker_host:            hosts.extend(["host.docker.internal", "host.openshell.internal"])        return hosts    def path(self, relative: str) -> Path:        path = (self.state_dir / relative).resolve()        if not path.is_relative_to(self.root) or not path.is_relative_to(self.state_dir):            raise ValueError("State path escapes AXIOM")        path.parent.mkdir(parents=True, exist_ok=True)        return path